const C=[{id:'youtube',name:'YouTube',icon:'▶',color:'#ed5959',tint:'#fff0f0',base:12840},{id:'facebook',name:'Facebook',icon:'f',color:'#4d83e5',tint:'#edf4ff',base:8420},{id:'instagram',name:'Instagram',icon:'◎',color:'#b06aca',tint:'#f8effc',base:15620},{id:'x',name:'X',icon:'𝕏',color:'#647187',tint:'#eff2f6',base:4860}];
const END='2026-10-23',START='2026-08-29',CURRENT='2026-10-19';
const fmt=n=>Number(n).toLocaleString('ko-KR'), sum=(a,k)=>a.reduce((s,r)=>s+(+r[k]||0),0), date=s=>new Date(s+'T00:00:00Z'), iso=d=>d.toISOString().slice(0,10), add=(s,n)=>iso(new Date(+date(s)+n*86400000)), monday=s=>add(s,-((date(s).getUTCDay()+6)%7)), short=s=>s.slice(5).replace('-','.');
let seed=93;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
const titles=['작은 습관이 만드는 큰 변화','이번 주 트렌드, 60초 요약','알아두면 달라지는 업무 팁 5가지','브랜드 뒤의 사람들','직접 써보고 고른 도구 모음','우리가 일하는 방식','시작하는 사람을 위한 가이드','댓글로 가장 많이 받은 질문','놓치기 아까운 이번 주 소식','하루를 바꾸는 세 가지 아이디어','새로운 프로젝트를 공개합니다','여러분의 선택은? A vs B'];
let posts=[],daily=[];for(let d=0;d<56;d++){let day=add(START,d);C.forEach((c,ci)=>{let count=(d+ci)%3===0?2:(d+ci)%5===0?0:1;for(let j=0;j<count;j++){let views=Math.round((140+random()*540)*(ci===0?1.45:ci===2?1.2:ci===3?.58:.75)*(1+d/150));let likes=Math.round(views*(.025+random()*.04)),saves=Math.round(views*random()*.014),shares=Math.round(views*random()*.012),reposts=Math.round(views*random()*.006);posts.push({date:day,channel:c.id,post_id:c.id+'-'+d+'-'+j,title:titles[(d*3+ci+j)%titles.length],type:ci===0?(j?'동영상':'Shorts'):ci===2?(d%2?'릴스':'캐러셀'):ci===3?'텍스트':'이미지',views,likes,saves,shares,reposts,conversions:likes+saves+shares+reposts,comments:Math.round(views*random()*.012)});}})}
// Same stable content ID appears twice in the raw export to demonstrate deduplication.
let currentPosts=posts.filter(p=>p.date>=CURRENT),rawTotal=sum(currentPosts,'views'),scaled=0;currentPosts.forEach((p,i)=>{p.views=i===currentPosts.length-1?12480-scaled:Math.round(p.views*12480/rawTotal);scaled+=p.views});
const raw=[...posts,{...posts[posts.length-1]}];posts=[...new Map(raw.map(p=>[p.channel+':'+p.post_id,p])).values()];
for(let d=0;d<56;d++){let day=add(START,d);C.forEach((c,ci)=>{let p=posts.filter(p=>p.date===day&&p.channel===c.id);daily.push({date:day,channel:c.id,followers:c.base+d*(ci===2?23:ci===0?14:ci===1?8:5),posts:p.length,views:sum(p,'views'),conversions:sum(p,'conversions'),comments:sum(p,'comments')})})}
let storageOK=true;function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{storageOK=false;return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{storageOK=false;return false}}
let goals=read('pulse-goals-v1',{[CURRENT]:10000}),period=7,selected='all',page=1,search='',sort='views',isUpdates=location.pathname.endsWith('updates.html');
function badge(c){return `<span class="channelbadge" style="--color:${c.color};--tint:${c.tint}">${c.icon}</span>`}function toast(t){document.querySelector('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.textContent=t;document.body.append(n);setTimeout(()=>n.remove(),3500)}
function range(){return period==='all'?START:add(END,1-period)}function rowsIn(a,start=range(),end=END){return a.filter(r=>r.date>=start&&r.date<=end)}function metrics(id,start=range(),end=END){let r=rowsIn(daily,start,end).filter(r=>id==='all'||r.channel===id);let last=r.filter(r=>r.date===end);return{followers:sum(last,'followers'),posts:sum(r,'posts'),views:sum(r,'views'),conversions:sum(r,'conversions'),comments:sum(r,'comments')}}
function change(id){if(period==='all')return null;let prevStart=add(range(),-period),prevEnd=add(range(),-1);if(prevStart<START)return null;let prev=metrics(id,prevStart,prevEnd).views,now=metrics(id).views;return prev?((now/prev-1)*100):null}
function changeLabel(id){let p=change(id);return p===null?'<span>— 비교 없음</span>':`<span class="${p>=0?'up':'down'}">${p>=0?'↗':'↘'} ${Math.abs(p).toFixed(1)}%</span>`}
function recommendation(week=CURRENT){let weeks=[1,2,3,4].map(n=>{let s=add(week,-7*n),e=add(s,6);return s>=START&&e<=END?{start:s,views:metrics('all',s,e).views}:null}).filter(Boolean);let avg=weeks.length?sum(weeks,'views')/weeks.length:10000;return{target:Math.ceil(avg*1.1/100)*100,avg:Math.round(avg),weeks}}
function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar"><a class="brand" href="index.html"><span class="logo">∿</span><span>social pulse<span style="color:#8794ff">.</span></span></a><div class="worklabel">WORKSPACE</div><a class="nav ${!isUpdates?'active':''}" href="index.html"><span class="navicon">▦</span><span>성과 대시보드</span></a><a class="nav ${isUpdates?'active':''}" href="updates.html"><span class="navicon">◷</span><span>업데이트 기록</span></a><div class="worklabel">CONNECTED CHANNELS</div><div class="sidechannels">${C.map(c=>`<div><i class="dot" style="background:${c.color}"></i>${c.name}</div>`).join('')}</div><div class="sidefoot"><span class="avatar">SP</span><div style="font-size:12px;color:#d5dce5">소셜 운영 워크스페이스<small>Demo workspace</small></div></div></aside><main><div class="topbar"><span>워크스페이스 <span style="margin:0 10px;color:#b1b8c1">/</span> ${isUpdates?'업데이트 기록':'성과 대시보드'}</span><div class="topright"><span class="demo">DEMO DATA</span><span class="status">데이터 기준 2026.10.23 · KST</span></div></div><div id="body"></div><footer class="footer"><span>© 2026 Social Pulse · 모든 채널의 성장을, 한눈에.</span><span>임의 데이터 · 실제 채널 미연결 &nbsp; <a href="updates.html">v1.1.0 ↗</a></span></footer></main><dialog id="goalDialog"><form id="goalForm"><div class="eyebrow">WEEKLY PLANNING</div><h2>이번 주 목표를 설정하세요</h2><p class="subtitle">매주 작은 성장을 쌓아보세요. 목표는 이 브라우저에 저장됩니다.</p><label for="weekInput">목표 주간 · 해당 날짜가 속한 월요일 기준</label><input id="weekInput" type="date" value="${CURRENT}" required><label for="goalInput">4개 채널 합산 주간 조회수 목표</label><input id="goalInput" type="number" min="1" max="1000000000" step="1" required><div class="modalnote" id="recommendText"></div><button type="button" class="btn small" id="useRecommended" style="margin-top:10px">추천 목표 적용</button><div class="actions"><button type="button" class="btn" id="cancelGoal">취소</button><button class="btn primary">목표 저장</button></div></form></dialog>`;if(isUpdates)renderUpdates();else render();bindModal();bindPreview()}
function spark(values,color){let max=Math.max(...values,1),points=values.map((n,i)=>`${i*100/(values.length-1||1)},${36-n/max*30}`).join(' ');return `<svg class="spark" viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg>`}
function render(){let weekly=metrics('all',CURRENT,add(CURRENT,6)>END?END:add(CURRENT,6)),target=goals[CURRENT]||10000,pct=weekly.views/target*100,rec=recommendation(),all=metrics('all'),activePosts=rowsIn(posts).filter(p=>selected==='all'||p.channel===selected),filtered=activePosts.filter(p=>p.title.includes(search)||C.find(c=>c.id===p.channel).name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b[sort]-a[sort]);let pages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,pages);
document.getElementById('body').innerHTML=`<div class="heading"><div><div class="eyebrow">SOCIAL ANALYTICS</div><h1>성과 대시보드</h1><p class="subtitle">흩어진 채널의 성과를 모아, 다음 성장을 발견하세요.</p></div><div class="actions"><button class="btn" id="exportAll">↓ 전체 CSV</button></div></div><section class="card goal" aria-label="이번 주 KPI"><div><div class="goalhead"><span class="label">⚑ 이번 주 핵심 목표</span><span class="label" style="font-size:10px">10.19 — 10.25</span></div><h2>주간 조회수 ${fmt(target)}회 달성 <span class="pill">${pct>=100?'목표 달성':'진행 중'}</span></h2><div class="goalnums"><span class="big">${fmt(weekly.views)}</span><span class="target">/ ${fmt(target)} 회</span></div><div class="progress" role="progressbar" aria-label="주간 목표 달성률" aria-valuenow="${Math.min(pct,100).toFixed(1)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(pct,100)}%"></span></div><div class="goalfoot"><span>${pct>=100?`목표보다 ${fmt(weekly.views-target)}회 더 달성했어요`:`목표까지 ${fmt(target-weekly.views)}회 남았어요`}</span><strong>${pct.toFixed(1)}% 달성</strong></div></div><div class="goalright"><h3>↗ 이전 성과를 바탕으로 한 추천 목표</h3><strong>${fmt(rec.target)} <span style="font-size:12px;font-weight:400;color:#7d89a5">회 / 주</span></strong><p>최근 완료된 ${rec.weeks.length}주 평균 ${fmt(rec.avg)}회 × 1.10<br>100회 단위 올림 · 임의 데이터 기반 추천</p><button class="btn small" id="openGoal">이번 주 목표 입력 / 수정 ↗</button></div></section><div class="sectionhead"><div><h2>채널 인사이트</h2><p>${short(range())} — ${short(END)} · ${period==='all'?'전체 56일':`최근 ${period}일`} · ${selected==='all'?'전체 채널':C.find(c=>c.id===selected).name} 분석</p></div><div class="segments" aria-label="분석 기간">${[1,7,30,'all'].map(p=>`<button data-period="${p}" class="${period===p?'active':''}" aria-pressed="${period===p}">${p==='all'?'전체':p+'일'}</button>`).join('')}</div></div><div class="channels">${C.map(c=>{let m=metrics(c.id),v=rowsIn(daily).filter(r=>r.channel===c.id),share=all.views?m.views/all.views*100:0;return `<button class="card channel ${selected===c.id?'selected':''}" data-channel="${c.id}" style="text-align:left;color:inherit" aria-pressed="${selected===c.id}"><div class="channelname">${badge(c)}${c.name}<span style="margin-left:auto;color:#b2bac6">↗</span></div><div class="channelvalue">${fmt(m.views)}<span style="font-size:11px;font-weight:400;color:#9aa2af;margin-left:6px">조회</span></div><div class="channelmeta">${changeLabel(c.id)}<span>${period==='all'?'전체 기간':'직전 동일 기간 대비'}</span></div>${spark(v.map(r=>r.views),c.color)}<div class="channelinsight">전체 조회수의 <b>${share.toFixed(1)}%</b> 기여 · 유효 게시물 <b>${m.posts}개</b></div></button>`}).join('')}</div>${selected!=='all'?'<button class="btn small" id="clearChannel" style="margin-top:10px">× 채널 필터 해제</button>':''}<div class="analysisrow"><section class="card chartcard"><div class="cardtitle"><h3>조회수 추이</h3><div class="legend">${C.filter(c=>selected==='all'||c.id===selected).map(c=>`<span><i class="dot" style="background:${c.color}"></i>${c.name}</span>`).join('')}</div></div>${lineChart()}<div class="chartlabels"><span>${short(range())}</span><span>${short(add(range(),Math.floor((+date(END)-+date(range()))/86400000/2)))}</span><span>${short(END)}</span></div></section><section class="card chartcard"><div class="cardtitle"><h3>채널별 조회수 비중</h3><small>전체 채널 기준</small></div>${C.map(c=>{let m=metrics(c.id),p=all.views?m.views/all.views*100:0;return `<div class="mixrow"><div class="mixname"><span><i class="dot" style="background:${c.color}"></i>${c.name}</span><span>${p.toFixed(1)}% <span style="color:#a0a8b3;margin-left:7px">${fmt(m.views)}</span></span></div><div class="mixbar"><span style="width:${p}%;background:${c.color}"></span></div></div>`}).join('')}<div class="hint">같은 기간의 4개 채널 합산 조회수 대비 비중입니다.</div></section></div><div class="sectionhead"><div><h2>지표별 성과</h2><p>채널 성과를 동일한 기준으로 비교해 보세요.</p></div><button class="btn small" id="exportMetrics">↓ 지표 CSV</button></div><section class="card tablewrap"><table><thead><tr><th>채널</th><th class="num">팔로워</th><th class="num">유효 게시항목</th><th class="num">조회수</th><th class="num">전환수 ⓘ</th><th class="num">댓글</th></tr></thead><tbody>${C.filter(c=>selected==='all'||c.id===selected).map(c=>metricRow(c.name,metrics(c.id),c)).join('')}${metricRow(selected==='all'?'전체 합계':'선택 채널 합계',metrics(selected),null)}</tbody></table><div class="tablefoot">팔로워: 기간 마지막 날의 채널별 수 합계(채널 간 중복 사용자 포함) · 게시항목: 선택 기간 업로드된 channel + post_id 고유 개수<br>전환수: 좋아요 + 저장 + 공유 + 리포스트(반응 횟수, 구매 전환·고유 사용자 아님) · 댓글은 별도 집계</div></section><div class="sectionhead"><div><h2>콘텐츠별 인사이트 <span style="font-size:11px;color:#959eab;font-weight:400;margin-left:6px">${filtered.length}개 콘텐츠</span></h2><p>선택 기간에 게시된 콘텐츠의 성과 순위입니다.</p></div><div class="actions"><input class="search" id="search" placeholder="콘텐츠 검색…" aria-label="콘텐츠 검색" value="${escapeHtml(search)}"><select class="filterselect" id="sort" aria-label="콘텐츠 정렬"><option value="views" ${sort==='views'?'selected':''}>조회수 높은 순</option><option value="conversions" ${sort==='conversions'?'selected':''}>전환수 높은 순</option><option value="comments" ${sort==='comments'?'selected':''}>댓글 많은 순</option></select><button class="btn small" id="exportContent">↓ CSV</button></div></div><section class="card tablewrap"><table><thead><tr><th>#</th><th>콘텐츠</th><th>채널</th><th>게시일</th><th class="num">조회수</th><th class="num">전환수</th><th class="num">댓글</th></tr></thead><tbody>${filtered.slice((page-1)*8,page*8).map((p,i)=>{let c=C.find(c=>c.id===p.channel);return `<tr><td class="rank">${String((page-1)*8+i+1).padStart(2,'0')}</td><td><div class="tablename"><button class="thumb-preview" data-preview="${p.post_id}" aria-label="${escapeHtml(p.title)} 썸네일 크게 보기"><img src="thumbnails/cover-${titles.indexOf(p.title)}.svg" alt="${escapeHtml(p.title)} 데모 썸네일" width="112" height="70" loading="lazy"><span class="thumb-type">${p.type}</span><span class="thumb-zoom" aria-hidden="true">⤢</span></button><div><div class="contenttitle">${p.title}</div><div class="contentsub">${p.type} · ${p.post_id}</div></div></div></td><td><span style="color:${c.color};font-size:11px">${c.name}</span></td><td style="font-size:11px;color:#8c96a4">${p.date.replaceAll('-','.')}</td><td class="num" style="font-weight:700">${fmt(p.views)}</td><td class="num">${fmt(p.conversions)}</td><td class="num">${fmt(p.comments)}</td></tr>`}).join('')}</tbody></table>${filtered.length?'':'<div class="empty">검색 결과가 없습니다.</div>'}<div class="pagination"><span>총 ${filtered.length}개 · 중복 게시물 제거 완료</span><div class="actions"><button class="btn small" id="prev" ${page<=1?'disabled':''}>‹</button><span>${page} / ${pages}</span><button class="btn small" id="next" ${page>=pages?'disabled':''}>›</button></div></div></section><div class="note">◷ 매주 월요일 09:00 KST · KPI 입력 리마인더 &nbsp; <button class="btn small" id="calendar">캘린더에 추가 ↗</button><br>목표는 이 브라우저에 저장됩니다. 실제 채널은 연결되지 않은 데모이며, 기준일은 2026.10.23으로 고정되어 있습니다. ${storageOK?'':'현재 브라우저 저장소를 사용할 수 없어 새로고침 시 목표가 초기화됩니다.'}</div>`;
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period==='all'?'all':+b.dataset.period;page=1;render()});document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{selected=selected===b.dataset.channel?'all':b.dataset.channel;page=1;render()});document.getElementById('clearChannel')?.addEventListener('click',()=>{selected='all';page=1;render()});document.getElementById('openGoal').onclick=openGoal;document.getElementById('sort').onchange=e=>{sort=e.target.value;page=1;render()};document.getElementById('search').oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;page=1;render();let el=document.getElementById('search');el.focus();el.setSelectionRange(pos,pos)};document.getElementById('prev').onclick=()=>{page--;render()};document.getElementById('next').onclick=()=>{page++;render()};document.getElementById('exportMetrics').onclick=()=>csvMetrics();document.getElementById('exportContent').onclick=()=>csvContent(filtered);document.getElementById('exportAll').onclick=()=>csvAll();document.getElementById('calendar').onclick=calendar;document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>openPreview(b.dataset.preview));
}
function metricRow(name,m,c){return `<tr class="${c?'':'total'}"><td>${c?`<span class="tablename">${badge(c)}${name}</span>`:name}</td>${['followers','posts','views','conversions','comments'].map(k=>`<td class="num">${fmt(m[k])}</td>`).join('')}</tr>`}
function lineChart(){let channels=C.filter(c=>selected==='all'||c.id===selected),days=[];for(let s=range();s<=END;s=add(s,1))days.push(s);let max=Math.max(...rowsIn(daily).filter(r=>selected==='all'||r.channel===selected).map(r=>r.views),1);let top=Math.ceil(max/500)*500;return `<svg viewBox="0 0 600 170" preserveAspectRatio="none" class="linechart" role="img" aria-label="${short(range())}부터 ${short(END)}까지 채널별 일별 조회수 추이">${[0,1,2,3].map(i=>`<line x1="33" y1="${10+i*48}" x2="595" y2="${10+i*48}" stroke="#edf0f4" stroke-dasharray="3 3"/><text x="26" y="${13+i*48}" fill="#a3abb7" text-anchor="end" font-size="8">${fmt(Math.round(top*(3-i)/3))}</text>`).join('')}${channels.map(c=>{let vals=days.map(d=>daily.find(r=>r.date===d&&r.channel===c.id)?.views||0);let pts=vals.map((n,i)=>`${33+i*560/(days.length-1||1)},${154-n/top*144}`).join(' ');return `<polyline points="${pts}" fill="none" stroke="${c.color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>${days.length===1?`<circle cx="33" cy="${154-vals[0]/top*144}" r="4" fill="${c.color}"/>`:''}`}).join('')}</svg>`}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openGoal(){document.getElementById('weekInput').value=CURRENT;updateRec();document.getElementById('goalDialog').showModal()}
function updateRec(){let w=monday(document.getElementById('weekInput').value||CURRENT),rec=recommendation(w);document.getElementById('goalInput').value=goals[w]||rec.target;document.getElementById('recommendText').textContent=`${w} ~ ${add(w,6)} · 추천 ${fmt(rec.target)}회. ${rec.weeks.length?`직전 완료된 ${rec.weeks.length}주 평균 ${fmt(rec.avg)}회 × 1.10, 100회 단위 올림.`:'이전 데이터가 없어 기본 기준 10,000회에 10%를 더해 제안합니다.'} 임의 데이터 기반입니다.`}
function bindModal(){document.getElementById('weekInput').onchange=updateRec;document.getElementById('cancelGoal').onclick=()=>document.getElementById('goalDialog').close();document.getElementById('useRecommended').onclick=()=>{document.getElementById('goalInput').value=recommendation(monday(document.getElementById('weekInput').value||CURRENT)).target};document.getElementById('goalForm').onsubmit=e=>{e.preventDefault();let w=monday(document.getElementById('weekInput').value),v=+document.getElementById('goalInput').value;if(!Number.isInteger(v)||v<1||v>1e9)return;goals[w]=v;let ok=save('pulse-goals-v1',goals);document.getElementById('goalDialog').close();if(!isUpdates)render();toast(ok?`${w} 주간 목표 ${fmt(v)}회 저장 완료`:'목표를 적용했지만 브라우저 저장소 오류로 저장되지 않았습니다.')}}
function download(name,text,type='text/csv;charset=utf-8'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(name,headers,rows){let esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';download(name,'\ufeff'+[headers,...rows].map(r=>r.map(esc).join(',')).join('\r\n'));toast('CSV 파일을 다운로드했습니다.')}
function csvMetrics(){let ch=C.filter(c=>selected==='all'||c.id===selected);csv(`channel_metrics_${range()}_${END}.csv`,['data_type','start_date','end_date','channel','followers_end','unique_posts','views','conversions','comments'],ch.map(c=>{let m=metrics(c.id);return['DEMO',range(),END,c.name,m.followers,m.posts,m.views,m.conversions,m.comments]}))}
function csvContent(p){csv(`content_${range()}_${END}.csv`,['data_type','date','channel','post_id','title','type','views','likes','saves','shares','reposts','conversions','comments'],p.map(r=>['DEMO',r.date,C.find(c=>c.id===r.channel).name,r.post_id,r.title,r.type,r.views,r.likes,r.saves,r.shares,r.reposts,r.conversions,r.comments]))}
function csvAll(){let headers=['data_type','record_type','date','channel','post_id','title','content_type','followers_end','unique_posts','views','likes','saves','shares','reposts','conversions','comments','week_start','weekly_goal'];let r=posts.map(p=>['DEMO','content',p.date,C.find(c=>c.id===p.channel).name,p.post_id,p.title,p.type,'',1,p.views,p.likes,p.saves,p.shares,p.reposts,p.conversions,p.comments,'','']);daily.forEach(d=>r.push(['DEMO','daily',d.date,C.find(c=>c.id===d.channel).name,'','','',d.followers,d.posts,d.views,'','','','',d.conversions,d.comments,'','']));Object.entries(goals).forEach(([w,g])=>r.push(['DEMO','goal','','','','','','','','','','','','','','',w,g]));csv('social_pulse_all_data.csv',headers,r)}
function calendar(){download('weekly-kpi-reminder.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Social Pulse//KPI//KO\r\nBEGIN:VEVENT\r\nUID:weekly-kpi-social-pulse-20261026\r\nDTSTAMP:20261023T000000Z\r\nDTSTART:20261026T000000Z\r\nDTEND:20261026T003000Z\r\nRRULE:FREQ=WEEKLY;BYDAY=MO\r\nSUMMARY:이번 주 소셜 KPI 목표 입력\r\nDESCRIPTION:지난주 실제 성과를 확인하고 이번 주 조회수 목표를 입력하세요.\r\nURL:https://social-pulse-kpi-oct23.skp-k-2881.chatgpt.site\r\nBEGIN:VALARM\r\nTRIGGER:PT0M\r\nACTION:DISPLAY\r\nDESCRIPTION:이번 주 KPI를 입력하세요\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n','text/calendar;charset=utf-8');toast('캘린더 앱에서 파일을 열어 정기 알림을 추가하세요.')}
function renderUpdates(){document.getElementById('body').innerHTML=`<div class="heading"><div><div class="eyebrow">WHAT’S NEW</div><h1>업데이트 기록</h1><p class="subtitle">Social Pulse가 더 나아지는 과정을 기록합니다.</p></div><a class="btn" href="index.html">대시보드로 돌아가기 ↗</a></div><section class="card timeline"><article class="release"><div><time datetime="2026-10-23">2026.10.23</time><p><span class="tag">v1.1.0 · 콘텐츠 썸네일</span></p></div><div><h2>이미지로 콘텐츠를 더 쉽게 구분하세요.</h2><ul><li>콘텐츠 주제에 맞춘 12종 데모 일러스트 썸네일 추가</li><li>썸네일을 누르면 큰 이미지와 채널·게시일·성과를 확인</li><li>콘텐츠 유형 배지 및 키보드 접근 지원</li></ul><p class="hint">현재 썸네일은 실제 게시물 이미지가 아닌 데모용 일러스트입니다.</p></div></article></section><section class="card timeline"><article class="release"><div><time datetime="2026-10-23">2026.10.23</time><p><span class="tag">v1.0.0 · 첫 출시</span></p></div><div><h2>모든 채널의 성장을, 한눈에.</h2><p class="subtitle">YouTube · Facebook · Instagram · X 통합 KPI 대시보드를 공개합니다.</p><ul><li>4개 채널 합산 주간 조회수 10,000회 목표와 달성률 표시</li><li>주간 목표 입력 및 브라우저 저장, 이전 4주 평균 기반 10% 성장 목표 제안</li><li>1일 · 7일 · 30일 · 전체 기간별 채널 인사이트 및 일별 조회수 추이</li><li>팔로워, 유효 게시항목, 조회수, 전환수, 댓글 비교</li><li>채널 + 게시물 ID를 기준으로 중복 게시물 제거</li><li>콘텐츠별 조회수 · 전환수 · 댓글 순위, 채널 필터와 검색</li><li>채널 지표 및 콘텐츠 CSV, 일별 데이터와 주간 목표를 포함한 전체 CSV 다운로드</li><li>매주 월요일 오전 9시 KPI 입력용 캘린더 파일 제공</li><li>모바일 · 태블릿 · 데스크톱 반응형 화면</li></ul></div></article></section><section class="card timeline"><div class="eyebrow">METRIC DEFINITIONS</div><h3 style="font-size:16px">데이터와 집계 기준</h3><p class="hint" style="font-size:12px">모든 수치는 임의로 생성한 데모 데이터입니다. 2026.08.29 ~ 10.23의 56일 데이터를 포함합니다. 주간 KPI는 월요일부터 일요일까지를 기준으로 하고, 이번 주 성과는 기준일까지 집계합니다. 조회수와 반응은 데모에서 게시일에 귀속한 일별 수치로 채널 지표와 콘텐츠 지표가 일치합니다. 팔로워는 기간 마지막 날의 스냅샷이며 기간 합산값이 아닙니다. 채널별 팔로워 합계는 채널 간 동일 사용자를 제거하지 않습니다.</p><p class="hint" style="font-size:12px">전환수는 좋아요·저장·공유·리포스트의 합계로 정의합니다. 댓글은 전환수에 포함하지 않습니다. 기간 비교는 직전 동일 길이 기간과 비교하며, 전체 기간에서는 비교를 제공하지 않습니다. 게시항목은 채널과 게시물 ID의 조합으로 중복 제거합니다.</p><p class="hint" style="font-size:12px">목표 입력값은 현재 기기의 브라우저에 저장됩니다. 외부 채널 API 동기화와 기기 간 공유는 아직 연결되지 않았습니다. 전체 CSV의 content·daily·goal 행은 별도 집계 단위이며, content와 daily를 합산하면 중복됩니다. 알림 대화에서 실제 데이터 기반 추천을 받으려면 실제 성과 또는 CSV를 제공해 주세요.</p></section>`}
function bindPreview(){let d=document.createElement('dialog');d.id='previewDialog';d.className='preview-dialog';d.innerHTML='<button type="button" class="preview-close" aria-label="미리보기 닫기">×</button><div id="previewBody"></div>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}
function openPreview(id){let p=posts.find(p=>p.post_id===id);if(!p)return;let c=C.find(c=>c.id===p.channel);document.getElementById('previewBody').innerHTML=`<img class="preview-image" src="thumbnails/cover-${titles.indexOf(p.title)}.svg" alt="${escapeHtml(p.title)} 데모 썸네일"><div class="preview-details"><div class="eyebrow">${c.name} · ${p.type}</div><h2>${escapeHtml(p.title)}</h2><p class="subtitle">${p.date.replaceAll('-','.')} · ${p.post_id}</p><div class="preview-metrics"><span>조회수<strong>${fmt(p.views)}</strong></span><span>전환수<strong>${fmt(p.conversions)}</strong></span><span>댓글<strong>${fmt(p.comments)}</strong></span></div><p class="hint">실제 게시물 이미지가 아닌 데모용 일러스트 썸네일입니다.</p></div>`;document.getElementById('previewDialog').showModal()}
